import{_ as i,o as n,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Notifications","description":"Inbox, unread state, in-app alerts, notification preferences, source-health notices, and current email/browser-delivery scope.","frontmatter":{"title":"Notifications","description":"Inbox, unread state, in-app alerts, notification preferences, source-health notices, and current email/browser-delivery scope.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"use-zenin/notifications.md","filePath":"use-zenin/notifications.md","lastUpdated":null}'),r={name:"use-zenin/notifications.md"};function a(s,e,l,d,c,p){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="notifications" tabindex="-1">Notifications</h1><p>Notifications keep you informed about your portfolio, sources, and journal without polling the app.</p><h2 id="inbox-and-unread-state" tabindex="-1">Inbox and unread state</h2><ul><li>Open <strong>Notifications</strong> to see your inbox.</li><li>Unread items are marked; mark them read as you handle them.</li><li>In-app alerts surface time-sensitive items (for example, a source-health notice) where you are working.</li></ul><h2 id="in-app-alerts" tabindex="-1">In-app alerts</h2><p>In-app alerts cover:</p><ul><li><strong>Source health</strong> — when a connection degrades, errors, or recovers.</li><li><strong>Journal reminders</strong> — when a detected trade is ready to be journaled (where enabled).</li><li><strong>Trade executions</strong> — when a connected account imports new fills.</li></ul><h2 id="notification-preferences" tabindex="-1">Notification preferences</h2><p>Set preferences to control which alerts you receive in-app. You can narrow what generates a notification so the inbox stays useful.</p><h2 id="source-health-notices" tabindex="-1">Source-health notices</h2><p>When a data source fails, delays, or returns partial data, Zenin raises a <strong>source-health notice</strong> with the specific reason where available. These notices are evidence of a provider issue, not an application error.</p><h2 id="email-and-browser-delivery-scope" tabindex="-1">Email and browser delivery scope</h2><ul><li><strong>Email</strong>: delivery depends on production email configuration and your preferences. Some notices are in-app only.</li><li><strong>Browser</strong>: browser delivery depends on the deployed configuration and your browser permissions; it is not guaranteed in every environment.</li></ul><p>If you expect an email and do not receive one, confirm email is enabled in preferences and that production email delivery is configured for your deployment.</p><hr><h2 id="what-this-does-does-not-do" tabindex="-1">What this does / does not do</h2><p><strong>What this does</strong></p><ul><li>Collects workspace notifications in one inbox with unread state.</li><li>Surfaces source-health and journal/trade alerts in-app.</li><li>Respects your notification preferences.</li></ul><p><strong>What it does not do</strong></p><ul><li>It does not guarantee email or browser delivery in every environment.</li><li>It does not retry indefinitely; source syncs follow each source&#39;s retry behavior.</li><li>It does not send trade-execution emails unless production email is configured and enabled.</li></ul><p><strong>Data source and freshness</strong></p><p>Notification events are generated by the backend from workspace activity and source sync results. Email delivery status depends on the configured email provider; in-app delivery is immediate within the session.</p>',22)])])}const f=i(r,[["render",a]]);export{h as __pageData,f as default};
